type SynergyPrincipleSectionProps = {
  data?: SynergyPrincipleSectionData | null;
};

export default function SynergyPrincipleSection({ data }: SynergyPrincipleSectionProps) {
  const content = data ?? DEFAULT_SYNERGY_PRINCIPLE;
  const headingLines = getTitleLines(content.Heading, 'multiline');
  const pillars = content.Pillars?.length ? content.Pillars : DEFAULT_SYNERGY_PRINCIPLE.Pillars!;
  const backgroundUrl =
    getMediaUrl(content.BackgroundImage) ??
    content.BackgroundImagePath ??
    DEFAULT_SYNERGY_PRINCIPLE.BackgroundImagePath!;

  return (
    <section className="relative overflow-hidden bg-black px-6 py-16 sm:px-8 lg:py-28">
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0"
        style={{
          backgroundImage: `url('${backgroundUrl}')`,
          backgroundSize: 'cover',
          backgroundPosition: 'center top',
        }}
      />
      <div aria-hidden="true" className="pointer-events-none absolute inset-0 " />

      <div className="relative z-10 mx-auto max-w-[1280px]">
        <div className="relative">
        

          <motion.div
            initial={{ opacity: 0, y: 24 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
            viewport={{ once: true }}
            className="relative z-10 max-w-5xl pr-0 lg:max-w-[90%] lg:pr-8"
          >
            <h2 className="responsive-large-h2 text-white">
              {headingLines.map((line, index) => (
                <span key={`${line}-${index}`} className="block">
                  {line}
                </span>
              ))}
            </h2>
            <p className="mt-6 max-w-2xl font-clother text-[16px] font-light text-white/80 lg:text-[18px]">
              {content.Subtitle}
            </p>
            <motion.div
              aria-hidden="true"
              className="pointer-events-none absolute left-[100%] bottom-0 z-[5] hidden h-[min(42vw,340px)] w-[min(34vw,280px)] lg:block xl:h-[380px] xl:w-[300px]"
              animate={{
                y: [0, -18, 0],
                rotate: [-1.5, 1.5, -1.5],
              }}
              transition={{
                duration: 6,
                ease: 'easeInOut',
                repeat: Infinity,
                repeatType: 'loop',
              }}
            >
              <AnimatedSvgVector
                viewBox="0 0 422 379"
                pathD={SYNERGY_VECTOR_PATH}
                stroke="#AEAEAE"
                strokeWidth={0.8}
                strokeMiterlimit={10}
                targetOpacity={0.5}
                duration={2.4}
                delay={0.3}
                className="h-full w-full"
              />
            </motion.div>
          </motion.div>

          <div className="relative z-10 mt-12 grid grid-cols-1 items-stretch gap-5 sm:mt-16 sm:grid-cols-2 sm:gap-6 lg:grid-cols-3 lg:gap-6 xl:gap-8">
            {pillars.map((pillar, index) => (
              <div
                key={`${pillar.Title}-${index}`}
                className={`flex h-full w-full ${getPillarCardTransformClass(index)} ${
                  index === 2 ? 'sm:col-span-2 sm:mx-auto sm:max-w-[calc(50%-0.75rem)] lg:col-span-1 lg:max-w-none' : ''
                }`}
              >
                <motion.article
                  initial={{ opacity: 0, y: 36 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.7, delay: index * 0.12 }}
                  viewport={{ once: true }}
                  className="flex h-full min-h-[340px] w-full flex-col rounded-[28px] border border-white/10 bg-[#ffffff]/25 p-6 backdrop-blur-sm transition-[border-color,box-shadow] duration-500 hover:border-white/20 sm:min-h-[420px] lg:p-8"
                >
                  <h3 className="responsive-clother-h3 font-bold text-white">
                    {pillar.Title}
                    <br />
                    {pillar.Subtitle}
                  </h3>
                  <p className="responsive-clother-paragraph mt-5 flex-1 text-white/78">
                    {pillar.Description}
                  </p>
                  {pillar.LinkText && (
                    <span className="responsive-clother-red-span mt-6 lowercase">
                      {pillar.LinkText}
                    </span>
                  )}
                </motion.article>
              </div>
            ))}
          </div>
        </div>

        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          transition={{ duration: 0.8, delay: 0.2 }}
          viewport={{ once: true }}
          className="relative z-10 mt-14 text-center lg:mt-20"
        >
          <p className="type-h4 font-bold text-white">{content.FooterLineOne}</p>
          {content.FooterLineTwo ? (
            <p className="type-h4 mt-2 font-bold text-white">{content.FooterLineTwo}</p>
          ) : null}
        </motion.div>
      </div>
    </section>
  );
}
